from flask import Flask, render_template, redirect, url_for
from flask_login import LoginManager, UserMixin, login_user, login_required, logout_user, current_user
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired, Length
from werkzeug.security import generate_password_hash, check_password_hash
class LoginForm(FlaskForm):
    username = StringField('Username', validators=[DataRequired(), Length(min=4, max=25)])
    password = PasswordField('Password', validators=[DataRequired(), Length(min=8, max=80)])
    submit = SubmitField('Log In')
login_manager = LoginManager()
def task_func(secret_key, template_folder):
    """
    Creates a Flask application with configured user authentication using Flask-Login.

    Parameters:
    secret_key (str): The secret key for the Flask application.
    template_folder (str): The path to the folder containing HTML templates.

    Returns:
    Flask: A Flask application instance configured for user authentication.
    """
    app = Flask(__name__, template_folder=template_folder)
    app.config['SECRET_KEY'] = secret_key

    # Initialize Flask-Login
    login_manager.init_app(app)
    login_manager.login_view = 'login'

    # Simple in-memory user storage
    class User(UserMixin):
        def __init__(self, id, username, password_hash):
            self.id = str(id)
            self.username = username
            self.password_hash = password_hash

    # Create a sample user
    users = {
        'testuser': User(1, 'testuser', generate_password_hash('password123'))
    }

    @login_manager.user_loader
    def load_user(user_id):
        """Load user by ID for Flask-Login."""
        for user in users.values():
            if user.id == str(user_id):
                return user
        return None

    @app.route('/')
    def index():
        """Redirect to login page or protected page based on authentication status."""
        if current_user.is_authenticated:
            return redirect(url_for('protected'))
        return redirect(url_for('login'))

    @app.route('/login', methods=['GET', 'POST'])
    def login():
        """Handle user login."""
        if current_user.is_authenticated:
            return redirect(url_for('protected'))

        form = LoginForm()
        if form.validate_on_submit():
            username = form.username.data
            password = form.password.data

            user = users.get(username)
            if user and check_password_hash(user.password_hash, password):
                login_user(user)
                return redirect(url_for('protected'))

        return render_template('login.html', form=form)

    @app.route('/protected')
    @login_required
    def protected():
        """Protected page that requires authentication."""
        return render_template('protected.html', user=current_user)

    @app.route('/logout')
    @login_required
    def logout():
        """Handle user logout."""
        logout_user()
        return redirect(url_for('login'))

    return app

import pandas as pd
import pytz
from datetime import datetime
from random import randint, seed as set_seed

def task_func(
    utc_datetime,
    cities=['New York', 'London', 'Beijing', 'Tokyo', 'Sydney'],
    weather_conditions=['Sunny', 'Cloudy', 'Rainy', 'Snowy', 'Stormy'],
    timezones={
        'New York': 'America/New_York',
        'London': 'Europe/London',
        'Beijing': 'Asia/Shanghai',
        'Tokyo': 'Asia/Tokyo',
        'Sydney': 'Australia/Sydney'
    },
    seed=42
):
    if not isinstance(utc_datetime, datetime):
        raise ValueError("utc_datetime must be a datetime object.")

    if not isinstance(cities, list) or not all(isinstance(city, str) for city in cities):
        raise ValueError("cities must be a list of strings.")

    if (
        not isinstance(weather_conditions, list)
        or len(weather_conditions) == 0
        or not all(isinstance(condition, str) for condition in weather_conditions)
    ):
        raise ValueError("weather_conditions must be a non-empty list of strings.")

    if not isinstance(timezones, dict):
        raise ValueError("timezones must be a dictionary.")

    if not all(isinstance(city, str) and isinstance(tz, str) for city, tz in timezones.items()):
        raise ValueError("timezones must map city names to timezone strings.")

    if not isinstance(seed, int):
        raise ValueError("seed must be an integer.")

    for city in cities:
        if city not in timezones:
            raise ValueError(f"Missing timezone for city: {city}")
        try:
            pytz.timezone(timezones[city])
        except Exception:
            raise ValueError(f"Invalid timezone for city '{city}': {timezones[city]}")

    if utc_datetime.tzinfo is None:
        utc_dt = pytz.utc.localize(utc_datetime)
    else:
        utc_dt = utc_datetime.astimezone(pytz.utc)

    set_seed(seed)
    report = []

    for city in cities:
        local_tz = pytz.timezone(timezones[city])
        local_dt = utc_dt.astimezone(local_tz)
        condition = weather_conditions[randint(0, len(weather_conditions) - 1)]

        report.append({
            'City': city,
            'Local Time': local_dt.strftime('%Y-%m-%d %H:%M:%S %Z'),
            'Weather Condition': condition
        })

    return pd.DataFrame(report)

