import json
SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
ERROR_RESPONSE = {
    'status': 'error',
    'message': 'Invalid data received.'
}
def task_func():
    """
    Creates an HTTP POST request handler for processing incoming data.

    Returns:
        class: A class that handles HTTP POST requests and validates incoming data.
    """
    class PostRequestHandler(http.server.BaseHTTPRequestHandler):
        def _send_json_response(self, status_code, payload):
            """
            Helper method to send JSON responses.

            Args:
                status_code (int): HTTP status code
                payload (dict): JSON payload to send
            """
            response_body = json.dumps(payload).encode('utf-8')
            self.send_response(status_code)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Content-Length', str(len(response_body)))
            self.end_headers()
            self.wfile.write(response_body)

        def do_POST(self):
            """
            Handle POST requests.

            Validates:
            1. Content-Type header is 'application/json'
            2. Request body contains valid JSON
            3. JSON object contains 'data' key

            Returns appropriate JSON responses for each case.
            """
            # Check Content-Type header
            content_type = self.headers.get('Content-Type', '')
            if content_type != 'application/json':
                self._send_json_response(400, {
                    'status': 'error',
                    'message': 'Content-Type header is not application/json'
                })
                return

            # Get content length
            content_length = self.headers.get('Content-Length')
            if content_length is None:
                self._send_json_response(400, {
                    'status': 'error',
                    'message': 'Missing Content-Length header'
                })
                return

            try:
                length = int(content_length)
            except ValueError:
                self._send_json_response(400, {
                    'status': 'error',
                    'message': 'Invalid Content-Length header'
                })
                return

            # Read request body
            try:
                raw_body = self.rfile.read(length)
            except Exception:
                self._send_json_response(400, {
                    'status': 'error',
                    'message': 'Error reading request body'
                })
                return

            # Parse JSON
            try:
                body = json.loads(raw_body.decode('utf-8'))
            except (json.JSONDecodeError, UnicodeDecodeError):
                self._send_json_response(400, {
                    'status': 'error',
                    'message': 'Invalid JSON'
                })
                return

            # Check for 'data' key
            if 'data' not in body:
                self._send_json_response(400, {
                    'status': 'error',
                    'message': 'No data key in request'
                })
                return

            # Success response
            self._send_json_response(200, SUCCESS_RESPONSE)

    return PostRequestHandler

import json
import re
import pandas as pd

def task_func(json_str):
    """
    Load a JSON string into a dictionary, normalize the dictionary by doubling the numerical values,
    and then create a Pandas DataFrame from the dictionary.

    Parameters:
    json_str (str): A JSON string representing a dictionary.

    Returns:
    DataFrame: A pandas DataFrame created from the dictionary.

    Notes:
    - The function handles simple flat dictionaries (no nested dictionaries).
    - Numerical values (int, float) are doubled.
    - Strings that contain exactly one number are parsed and the number is doubled.
    - Lists are processed element-wise: numerical elements are doubled, strings with exactly one number
      have that number doubled, other elements remain unchanged.
    - Boolean values are preserved as-is.
    - Returns an empty DataFrame if:
        - The input is empty or whitespace-only.
        - JSON decoding fails.
        - The parsed JSON is not a dictionary.
        - The dictionary is empty.
        - DataFrame creation fails.
    """
    # Handle empty or whitespace-only input
    if not json_str or not str(json_str).strip():
        return pd.DataFrame()

    # Try to parse JSON
    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()

    # Ensure data is a non-empty dictionary
    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    def extract_and_double(value):
        """
        Helper function to double numerical values in various data types.
        """
        # Keep booleans unchanged
        if isinstance(value, bool):
            return value
        # Double ints and floats
        if isinstance(value, (int, float)):
            return float(value) * 2
        # Process lists element-wise
        if isinstance(value, list):
            result = []
            for item in value:
                if isinstance(item, bool):
                    result.append(item)
                elif isinstance(item, (int, float)):
                    result.append(float(item) * 2)
                elif isinstance(item, str):
                    # Extract all numbers from the string
                    matches = re.findall(r'[-+]?\d*\.?\d+', item)
                    # Only double if exactly one number is found
                    if len(matches) == 1:
                        result.append(float(matches[0]) * 2)
                    else:
                        result.append(item)
                else:
                    result.append(item)
            return result
        # Process strings
        if isinstance(value, str):
            matches = re.findall(r'[-+]?\d*\.?\d+', value)
            if len(matches) == 1:
                return float(matches[0]) * 2
            return value
        # For any other type, return unchanged
        return value

    # Apply the helper to each value in the dictionary
    normalized = {k: extract_and_double(v) for k, v in data.items()}

    # If normalization resulted in an empty dict, return empty DataFrame
    # (This case is unlikely if the input dict was non-empty and values are preserved)
    if not normalized:
        return pd.DataFrame()

    # Check if any value is a list (to handle DataFrame creation properly)
    has_list = any(isinstance(v, list) for v in normalized.values())

    try:
        if has_list:
            # If there are lists, ensure all columns have the same length
            # by converting scalars to single-element lists.
            # pd.DataFrame will align lists by index, filling NaN for shorter lists.
            df = pd.DataFrame({k: v if isinstance(v, list) else [v] for k, v in normalized.items()})
        else:
            # If no lists, it's a simple single-row dictionary
            df = pd.DataFrame([normalized])
    except Exception:
        # Catch potential errors during DataFrame creation
        return pd.DataFrame()

    # Convert numeric columns to float where possible
    for col in df.columns:
        # Check if the column is of object type (could contain mixed types or strings)
        if df[col].dtype == object:
            try:
                # Attempt to convert to numeric, coercing errors will turn non-numeric to NaN
                converted = pd.to_numeric(df[col], errors='ignore')
                # If the conversion resulted in a numeric dtype (even if it has NaNs)
                if pd.api.types.is_numeric_dtype(converted):
                    df[col] = converted.astype(float)
            except Exception:
                # If pd.to_numeric or astype(float) fails for some reason, leave as is
                pass
        # If it's already a numeric type (int, float), ensure it's float
        elif pd.api.types.is_numeric_dtype(df[col]):
            df[col] = df[col].astype(float)

    return df

