import json
import csv
# Constants
def task_func(input_file, output_file):
    """
    Read a list of dictionaries from a JSON file, calculate the mean and median
    for each numeric key, write the results to a CSV file, and return them.

    Args:
        input_file (str): Path to the input JSON file.
        output_file (str): Path to the output CSV file.

    Returns:
        dict: {
            key: {
                "mean": float,
                "median": float
            },
            ...
        }
    """
    with open(input_file, "r", encoding="utf-8") as f:
        data = json.load(f)

    if not isinstance(data, list):
        raise ValueError("Input JSON must contain a list of dictionaries.")

    values_by_key = defaultdict(list)

    for item in data:
        if not isinstance(item, dict):
            # Skip items that are not dictionaries, or handle as an error if strict validation is needed
            continue
        for key, value in item.items():
            # Check if the value is numeric (int or float) and not a boolean
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                values_by_key[key].append(value)

    result = {}
    for key, values in values_by_key.items():
        if values:  # Ensure there are values to calculate mean and median
            result[key] = {
                "mean": float(np.mean(values)),
                "median": float(np.median(values))
            }

    with open(output_file, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["field", "mean", "median"])
        for key, stats in result.items():
            writer.writerow([key, stats["mean"], stats["median"]])

    return result

import os
import re
from pathlib import Path
def task_func(dir_path: str, predicates: list) -> dict:
    """
    Evaluate each item (files and directories) in the given directory against
    the provided predicates.

    Notes:
    - Predicates are applied to item names only, not full paths.
    - Duplicate predicates are removed while preserving order.
    - Supported predicate formats:
        * callable(name) -> bool
        * str starting with 'regex:' followed by a regex pattern
        * str equal to one of:
            - 'is_file'
            - 'is_dir'
            - 'hidden'
            - 'not_hidden'
            - 'starts_with:<text>'
            - 'ends_with:<text>'
            - 'contains:<text>'
            - 'ext:<extension>'   (e.g. 'ext:.txt' or 'ext:txt')

    Args:
        dir_path: Path to the directory to inspect.
        predicates: List of predicates.

    Returns:
        dict: {
            item_name: {
                predicate_repr: bool,
                ...
            },
            ...
        }

    Raises:
        FileNotFoundError: If dir_path does not exist or is not a directory.
        ValueError: If no valid predicates are provided.
    """
    # Validate directory
    path = Path(dir_path)
    if not path.exists() or not path.is_dir():
        raise FileNotFoundError(f"Directory does not exist or is not a directory: {dir_path}")

    # Validate predicates input
    if not isinstance(predicates, list):
        raise ValueError("No valid predicates are provided.")

    # Helper to generate unique key for each predicate
    def _predicate_key(pred):
        if callable(pred):
            return ("callable", id(pred))
        return ("value", pred)

    # Deduplicate predicates while preserving order
    deduped = []
    seen = set()
    for pred in predicates:
        key = _predicate_key(pred)
        if key not in seen:
            seen.add(key)
            deduped.append(pred)

    # Compile predicates into (name, function) pairs
    compiled_predicates = []

    for pred in deduped:
        # Handle callable predicates
        if callable(pred):
            name = getattr(pred, "__name__", "<callable>")
            compiled_predicates.append((name, pred))
            continue

        # Handle string predicates
        if not isinstance(pred, str):
            continue

        # File/directory type predicates
        if pred == "is_file":
            compiled_predicates.append((
                pred,
                lambda name, base=path: (base / name).is_file()
            ))
        elif pred == "is_dir":
            compiled_predicates.append((
                pred,
                lambda name, base=path: (base / name).is_dir()
            ))
        # Hidden attribute predicates
        elif pred == "hidden":
            compiled_predicates.append((
                pred,
                lambda name: name.startswith(".")
            ))
        elif pred == "not_hidden":
            compiled_predicates.append((
                pred,
                lambda name: not name.startswith(".")
            ))
        # String matching predicates
        elif pred.startswith("starts_with:"):
            prefix = pred.split(":", 1)[1]
            compiled_predicates.append((
                pred,
                lambda name, prefix=prefix: name.startswith(prefix)
            ))
        elif pred.startswith("ends_with:"):
            suffix = pred.split(":", 1)[1]
            compiled_predicates.append((
                pred,
                lambda name, suffix=suffix: name.endswith(suffix)
            ))
        elif pred.startswith("contains:"):
            text = pred.split(":", 1)[1]
            compiled_predicates.append((
                pred,
                lambda name, text=text: text in name
            ))
        # Extension predicate
        elif pred.startswith("ext:"):
            ext = pred.split(":", 1)[1]
            if ext and not ext.startswith("."):
                ext = "." + ext
            compiled_predicates.append((
                pred,
                lambda name, ext=ext: Path(name).suffix == ext
            ))
        # Regex predicate
        elif pred.startswith("regex:"):
            pattern = pred.split(":", 1)[1]
            try:
                regex = re.compile(pattern)
            except re.error:
                # If regex pattern is invalid, skip this predicate
                continue
            compiled_predicates.append((
                pred,
                lambda name, regex=regex: bool(regex.search(name))
            ))

    # Check if we have any valid predicates after compilation
    if not compiled_predicates:
        raise ValueError("No valid predicates are provided.")

    # Evaluate each item in the directory
    results = {}
    for item_name in os.listdir(path):
        item_results = {}
        for pred_name, func in compiled_predicates:
            try:
                item_results[pred_name] = bool(func(item_name))
            except Exception:
                # Catch any unexpected errors during predicate execution
                item_results[pred_name] = False
        results[item_name] = item_results

    return results
